const outboundLanguageFixes = Object.fromEntries(
  Object.entries(inboundLanguageFixes).map(([language, additions]) => [
    language,
    Object.fromEntries(
      Object.entries(additions).map(([key, value]) => [
        key
          .replaceAll("Inbound", "Outbound")
          .replaceAll("inbound", "outbound")
          .replaceAll("qty_inbound", "qty_outbound"),
        String(value)
          .replaceAll("Inbound", "Outbound")
          .replaceAll("inbound", "outbound")
          .replaceAll("入库", "出库")
          .replaceAll("nhập", "xuất")
          .replaceAll("Nhập", "Xuất")
          .replaceAll("qty_inbound", "qty_outbound"),
      ]),
    ),
  ]),
);

Object.entries(outboundLanguageFixes).forEach(([language, additions]) => {
  dictionaries[language] = { ...(dictionaries[language] || {}), ...additions };
});

