let textNodes = new WeakMap();
let attrValues = new WeakMap();
const translatedAttrNames = ["placeholder", "title", "aria-label", "alt", "label"];
let observer;
let scheduled = false;
let toastPatched = false;
let reverseTranslationMap;

const normalizeLanguage = (language) => String(language || "en").split("-")[0];
const normalizeText = (text) => String(text ?? "").replace(/\s+/g, " ").trim();
const preserveOriginalSpacing = (original, translated) => {
  if (typeof original !== "string") return translated;
  const leading = original.match(/^\s*/)?.[0] || "";
  const trailing = original.match(/\s*$/)?.[0] || "";
  return `${leading}${translated}${trailing}`;
};

function getReverseTranslationMap() {
  if (reverseTranslationMap) return reverseTranslationMap;
  reverseTranslationMap = new Map();
  Object.values(dictionaries).forEach((dictionary) => {
    Object.entries(dictionary).forEach(([source, translated]) => {
      const normalizedSource = normalizeText(source);
      const normalizedTranslated = normalizeText(translated);
      if (normalizedSource) reverseTranslationMap.set(normalizedSource, normalizedSource);
      if (normalizedTranslated) reverseTranslationMap.set(normalizedTranslated, normalizedSource);
    });
  });
  return reverseTranslationMap;
}

function getCanonicalText(text) {
  return getReverseTranslationMap().get(normalizeText(text)) || normalizeText(text);
}

function getDictionary(language) {
  const resolvedLanguage = normalizeLanguage(language || i18n.resolvedLanguage || i18n.language);
  return dictionaries[resolvedLanguage] || {};
}

function joinTranslatedParts(parts, dictionary, separator = " ") {
  return parts.map((part) => translateText(part, dictionary)).join(separator);
}

function translatePattern(canonicalText, dictionary) {
  const selectedMatch = canonicalText.match(/^(\d[\d,]*) selected$/i);
  if (selectedMatch && dictionary.Selected) return `${selectedMatch[1]} ${dictionary.Selected}`;

  const selectedInboundOrdersMatch = canonicalText.match(/^(\d[\d,]*) selected inbound orders$/i);
  if (selectedInboundOrdersMatch && dictionary["{count} selected inbound orders"]) {
    return dictionary["{count} selected inbound orders"].replace("{count}", selectedInboundOrdersMatch[1]);
  }

  const selectedOutboundOrdersMatch = canonicalText.match(/^(\d[\d,]*) selected outbound orders$/i);
  if (selectedOutboundOrdersMatch && dictionary["{count} selected outbound orders"]) {
    return dictionary["{count} selected outbound orders"].replace("{count}", selectedOutboundOrdersMatch[1]);
  }

  const maxQtyMatch = canonicalText.match(/^Max ([\d,]+)$/i);
  if (maxQtyMatch && dictionary.Max) {
    return `${dictionary.Max} ${maxQtyMatch[1]}`;
  }

  const outboundIdLabelMatch = canonicalText.match(/^Outbound ID:\s*(.+)$/i);
  if (outboundIdLabelMatch && dictionary["Outbound ID"]) {
    return `${dictionary["Outbound ID"]}: ${outboundIdLabelMatch[1]}`;
  }

  const deleteOutboundDraftMatch = canonicalText.match(/^Delete outbound draft (.+)\?\s*This action cannot be undone\.$/i);
  if (deleteOutboundDraftMatch && dictionary["Delete outbound draft"]) {
    return `${dictionary["Delete outbound draft"]} ${deleteOutboundDraftMatch[1]}? ${dictionary["This action cannot be undone."] || "This action cannot be undone."}`;
  }

  const selectedItemMatch = canonicalText.match(/^(\d[\d,]*) (selected product\(s\)|selected mapped SKU\(s\)|selected item\(s\)|selected SKU\(s\))$/i);
  if (selectedItemMatch) return `${selectedItemMatch[1]} ${translateText(selectedItemMatch[2], dictionary)}`;

  const subAccountSelectedMatch = canonicalText.match(/^(\d[\d,]*) sub-account(s)? selected$/i);
  if (subAccountSelectedMatch) {
    const key = subAccountSelectedMatch[1] === "1" ? "sub-account selected" : "sub-accounts selected";
    return `${subAccountSelectedMatch[1]} ${dictionary[key] || key}`;
  }

  const mappedCountMatch = canonicalText.match(/^(\d[\d,]*) mapped$/i);
  if (mappedCountMatch && dictionary.mapped) return `${mappedCountMatch[1]} ${dictionary.mapped}`;

  const availableInventoryMatch = canonicalText.match(/^Available Inventory:\s*(.+)$/i);
  if (availableInventoryMatch && dictionary["Available Inventory"]) {
    return `${dictionary["Available Inventory"]}: ${availableInventoryMatch[1]}`;
  }

  const changeMappingPackageMatch = canonicalText.match(/^Change Mapping _ Warehouse Package No:\s*(.+)$/i);
  if (changeMappingPackageMatch && dictionary["Change Mapping _ Warehouse Package No"]) {
    return `${dictionary["Change Mapping _ Warehouse Package No"]}: ${changeMappingPackageMatch[1]}`;
  }

  const erpWarehouseMatch = canonicalText.match(/^ERP Warehouse:\s*(.+)$/i);
  if (erpWarehouseMatch && dictionary["ERP Warehouse"]) {
    return `${dictionary["ERP Warehouse"]}: ${erpWarehouseMatch[1]}`;
  }

  const completedPackagingMatch = canonicalText.match(/^Are you sure you have completed packaging\s+(\d[\d,]*)\s+(TikTok\s+)?order\(s\)\?$/i);
  if (completedPackagingMatch && dictionary["Are you sure you have completed packaging"]) {
    const suffixKey = completedPackagingMatch[2] ? "TikTok order(s)?" : "order(s)?";
    return `${dictionary["Are you sure you have completed packaging"]} ${completedPackagingMatch[1]} ${dictionary[suffixKey] || suffixKey}`;
  }

  const multiPlatformConfirmMatch = canonicalText.match(/^Process (\d[\d,]*) selected Shopee and TikTok order\(s\) to (pack|push)\?$/i);
  if (multiPlatformConfirmMatch && dictionary["Process {count} selected Shopee and TikTok order(s) to {action}?"]) {
    return dictionary["Process {count} selected Shopee and TikTok order(s) to {action}?"]
      .replace("{count}", multiPlatformConfirmMatch[1])
      .replace("{action}", translateText(multiPlatformConfirmMatch[2].toLowerCase(), dictionary));
  }

  const mixedActionFailedMatch = canonicalText.match(/^(\d[\d,]*) order\(s\) failed to (pack|push)$/i);
  if (mixedActionFailedMatch && dictionary["{count} order(s) failed to {action}"]) {
    return dictionary["{count} order(s) failed to {action}"]
      .replace("{count}", mixedActionFailedMatch[1])
      .replace("{action}", translateText(mixedActionFailedMatch[2].toLowerCase(), dictionary));
  }

  const mixedActionSuccessMatch = canonicalText.match(/^(\d[\d,]*) selected order\(s\) (packed successfully|ready to print)$/i);
  if (mixedActionSuccessMatch) {
    const templateKey = mixedActionSuccessMatch[2].toLowerCase() === "packed successfully"
      ? "{count} selected order(s) packed successfully"
      : "{count} selected order(s) ready to print";
    if (dictionary[templateKey]) return dictionary[templateKey].replace("{count}", mixedActionSuccessMatch[1]);
  }

  const orderActionFailedMatch = canonicalText.match(/^Order (pack|push) failed$/i);
  if (orderActionFailedMatch && dictionary["Order {action} failed"]) {
    return dictionary["Order {action} failed"].replace(
      "{action}",
      translateText(orderActionFailedMatch[1].toLowerCase(), dictionary)
    );
  }

  const orderNumberMatch = canonicalText.match(/^Order Number:\s*(.+)$/i);
  if (orderNumberMatch && dictionary["Order Number:"]) {
    return `${dictionary["Order Number:"]} ${orderNumberMatch[1]}`;
  }

  const platformStatusMatch = canonicalText.match(/^The platform status is - (.+?) - (.+?)\. Total item quantity: (.+)$/i);
  if (platformStatusMatch) {
    const prefix = dictionary["The platform status is"] || "The platform status is";
    const quantity = dictionary["Total item quantity"] || "Total item quantity";
    return `${prefix} - ${platformStatusMatch[1]} - ${translateText(platformStatusMatch[2], dictionary)}. ${quantity}: ${platformStatusMatch[3]}`;
  }

  const tabCountMatch = canonicalText.match(/^(All|Mapped|Unmapped) \((\d[\d,]*)\)$/i);
  if (tabCountMatch && dictionary[tabCountMatch[1]]) return `${dictionary[tabCountMatch[1]]} (${tabCountMatch[2]})`;

  const labelCountMatch = canonicalText.match(/^(.+?) \(([\d_][\d,_ ]*)\)$/);
  if (labelCountMatch && dictionary[labelCountMatch[1]]) {
    return `${dictionary[labelCountMatch[1]]} (${labelCountMatch[2]})`;
  }

  const unlinkStoreMatch = canonicalText.match(/^Are you sure you want to unlink (.+)\? This action cannot be undone\.$/i);
  if (unlinkStoreMatch) {
    const prefix = dictionary["Are you sure you want to unlink"] || "Are you sure you want to unlink";
    const suffix = dictionary["This action cannot be undone."] || "This action cannot be undone.";
    return `${prefix} ${unlinkStoreMatch[1]}? ${suffix}`;
  }

  const showingMatch = canonicalText.match(/^Showing (\d[\d,]*) to (\d[\d,]*) of (\d[\d,]*) results$/i);
  if (showingMatch && dictionary.Showing && dictionary.of && dictionary.results) {
    return `${dictionary.Showing} ${showingMatch[1]} - ${showingMatch[2]} ${dictionary.of} ${showingMatch[3]} ${dictionary.results}`;
  }

  const showingRangeMatch = canonicalText.match(/^Showing (\d[\d,]*)\s*[-–]\s*(\d[\d,]*) of (\d[\d,]*)(?: (products|records|items|orders|warehouses|stores|sub accounts|roles|inventory items|skus))?$/i);
  if (showingRangeMatch && dictionary.Showing && dictionary.of) {
    const itemLabel = showingRangeMatch[4] ? ` ${translateText(showingRangeMatch[4].toLowerCase(), dictionary)}` : "";
    return `${dictionary.Showing} ${showingRangeMatch[1]}-${showingRangeMatch[2]} ${dictionary.of} ${showingRangeMatch[3]}${itemLabel}`;
  }

  const pageOfMatch = canonicalText.match(/^Page (\d[\d,]*) of (\d[\d,]*)$/i);
  if (pageOfMatch && dictionary.Page && dictionary.of) {
    return `${dictionary.Page} ${pageOfMatch[1]} ${dictionary.of} ${pageOfMatch[2]}`;
  }

  const pleaseSelectMatch = canonicalText.match(/^Please select at least one (.+) first\.$/i);
  if (pleaseSelectMatch) {
    const item = translateText(pleaseSelectMatch[1], dictionary);
    return dictionary["Please select at least one {item} first."]?.replace("{item}", item)
      || `${dictionary["Please select at least one"] || "Please select at least one"} ${item} ${dictionary.first || "first"}.`;
  }

  const pleaseSelectMinimumMatch = canonicalText.match(/^Please select minimum one (.+)$/i);
  if (pleaseSelectMinimumMatch) {
    const itemText = pleaseSelectMinimumMatch[1];
    const item = itemText.toLowerCase() === "inbound"
      ? dictionary.Inbound || "inbound"
      : translateText(itemText, dictionary);
    return dictionary["Please select at least one {item} first."]?.replace("{item}", item)
      || `${dictionary["Please select at least one"] || "Please select minimum one"} ${item}`;
  }

  const exportedMatch = canonicalText.match(/^(\d[\d,]*) (.+)\(s\) exported successfully\.$/i);
  if (exportedMatch) {
    const item = translateText(exportedMatch[2], dictionary);
    return dictionary["{count} {item}(s) exported successfully."]
      ?.replace("{count}", exportedMatch[1])
      .replace("{item}", item)
      || `${exportedMatch[1]} ${item} ${dictionary["exported successfully"] || "exported successfully"}.`;
  }

  const deletedMatch = canonicalText.match(/^(\d[\d,]*) (.+)\(s\) deleted successfully$/i);
  if (deletedMatch) {
    const item = translateText(deletedMatch[2], dictionary);
    return dictionary["{count} {item}(s) deleted successfully"]
      ?.replace("{count}", deletedMatch[1])
      .replace("{item}", item)
      || `${deletedMatch[1]} ${item} ${dictionary["deleted successfully"] || "deleted successfully"}`;
  }

  const failedPackMatch = canonicalText.match(/^(\d[\d,]*) (Shopee|TikTok) (AWB )?order\(s\) failed(?: to pack)?$/i);
  if (failedPackMatch) {
    const awb = failedPackMatch[3] || "";
    return dictionary["{count} {platform} {awb}order(s) failed"]
      ?.replace("{count}", failedPackMatch[1])
      .replace("{platform}", failedPackMatch[2])
      .replace("{awb}", awb)
      || `${failedPackMatch[1]} ${failedPackMatch[2]} ${awb}${dictionary["order(s) failed"] || "order(s) failed"}`;
  }

  const skuCreatedMatch = canonicalText.match(/^SKU "(.+)" created successfully$/i);
  if (skuCreatedMatch && (dictionary["SKU {sku} created successfully"] || dictionary["SKU created successfully"])) {
    const template = dictionary["SKU {sku} created successfully"] || dictionary["SKU created successfully"];
    return template.replace("{sku}", `"${skuCreatedMatch[1]}"`);
  }

  const skuUpdatedMatch = canonicalText.match(/^SKU "(.+)" updated successfully$/i);
  if (skuUpdatedMatch && (dictionary["SKU {sku} updated successfully"] || dictionary["SKU updated successfully"])) {
    const template = dictionary["SKU {sku} updated successfully"] || dictionary["SKU updated successfully"];
    return template.replace("{sku}", `"${skuUpdatedMatch[1]}"`);
  }

  const easyParcelAwbMatch = canonicalText.match(/^EasyParcel AWB generated: (.+)$/i);
  if (easyParcelAwbMatch) {
    return `${dictionary["EasyParcel AWB generated"] || "EasyParcel AWB generated"}: ${easyParcelAwbMatch[1]}`;
  }

  const manualInboundCreatedMatch = canonicalText.match(/^(Manual inbound|Inbound draft) (.+) created successfully$/i);
  if (manualInboundCreatedMatch) {
    const template = dictionary["{type} {id} created successfully"];
    if (template) {
      return template
        .replace("{type}", translateText(manualInboundCreatedMatch[1], dictionary))
        .replace("{id}", manualInboundCreatedMatch[2]);
    }
  }

  const inboundOnTheWayMatch = canonicalText.match(/^Inbound (.+) (?:is now |marked as )On The Way$/i);
  if (inboundOnTheWayMatch && dictionary["Inbound {id} is now On The Way"]) {
    return dictionary["Inbound {id} is now On The Way"].replace("{id}", inboundOnTheWayMatch[1]);
  }

  const outboundOnTheWayMatch = canonicalText.match(/^Outbound (.+) (?:is now |marked as )On The Way$/i);
  if (outboundOnTheWayMatch && dictionary["Outbound {id} is now On The Way"]) {
    return dictionary["Outbound {id} is now On The Way"].replace("{id}", outboundOnTheWayMatch[1]);
  }

  const inboundReceivedMatch = canonicalText.match(/^Inbound (.+) received [—-] stock updated$/i);
  if (inboundReceivedMatch && dictionary["Inbound {id} received — stock updated"]) {
    return dictionary["Inbound {id} received — stock updated"].replace("{id}", inboundReceivedMatch[1]);
  }

  const enterActualReceivedMatch = canonicalText.match(/^Enter actual quantities received for (.+)$/i);
  if (enterActualReceivedMatch && dictionary["Enter actual quantities received for {id}"]) {
    return dictionary["Enter actual quantities received for {id}"].replace("{id}", translateText(enterActualReceivedMatch[1], dictionary));
  }

  const confirmShipmentMatch = canonicalText.match(/^Confirm shipment details for (.+)$/i);
  if (confirmShipmentMatch && dictionary["Confirm shipment details for {id}"]) {
    return dictionary["Confirm shipment details for {id}"].replace("{id}", confirmShipmentMatch[1]);
  }

  const reverseQtyInboundMatch = canonicalText.match(/^(.+)?This will reverse qty_inbound counters\.$/i);
  if (reverseQtyInboundMatch && dictionary["This will reverse qty_inbound counters."]) {
    const prefix = reverseQtyInboundMatch[1]?.trim() || "";
    return `${prefix ? `${prefix} ` : ""}${dictionary["This will reverse qty_inbound counters."]}`;
  }

  const missingInfoMatch = canonicalText.match(/^Missing (.+) information: (.+)$/i);
  if (missingInfoMatch) {
    const service = translateText(missingInfoMatch[1], dictionary);
    return `${dictionary.Missing || "Missing"} ${service} ${dictionary.information || "information"}: ${missingInfoMatch[2]}`;
  }

  const fieldRequiredMatch = canonicalText.match(/^(.+) is required$/i);
  if (fieldRequiredMatch) {
    const field = translateText(fieldRequiredMatch[1], dictionary);
    return dictionary["{field} is required"]?.replace("{field}", field) || `${field} ${dictionary["is required"] || "is required"}`;
  }

  const searchByMatch = canonicalText.match(/^Search by (.+)$/i);
  if (searchByMatch && dictionary.Search) {
    return `${dictionary.Search} ${translateText(searchByMatch[1], dictionary)}`;
  }

  const loadingMatch = canonicalText.match(/^Loading (.+)\.\.\.$/i);
  if (loadingMatch && dictionary.Loading) {
    return `${dictionary.Loading} ${translateText(loadingMatch[1], dictionary)}...`;
  }

  const areYouSureDeleteMatch = canonicalText.match(/^Are you sure you want to delete (.+)\?$/i);
  if (areYouSureDeleteMatch) {
    return dictionary["Are you sure you want to delete {item}?"]?.replace("{item}", translateText(areYouSureDeleteMatch[1], dictionary))
      || `${dictionary["Are you sure you want to delete"] || "Are you sure you want to delete"} ${translateText(areYouSureDeleteMatch[1], dictionary)}?`;
  }

  return null;
}

function translateText(value, dictionary = getDictionary()) {
  if (typeof value !== "string") return value;
  const text = normalizeText(value);
  if (!text) return value;
  const canonicalText = getCanonicalText(text);
  const translated = dictionary[canonicalText] || dictionary[text] || translatePattern(canonicalText, dictionary);
  return translated ? preserveOriginalSpacing(value, translated) : value;
}

export function translateStaticText(value, language) {
  return translateText(value, getDictionary(language));
}

function translateToastValue(value) {
  if (typeof value !== "string") return value;
  return translateText(value, getDictionary());
}

function translateToastOptions(options) {
  if (!options || typeof options !== "object") return options;
  const next = { ...options };
  if (typeof next.description === "string") next.description = translateToastValue(next.description);
  if (typeof next.action?.label === "string") {
    next.action = { ...next.action, label: translateToastValue(next.action.label) };
  }
  if (typeof next.cancel?.label === "string") {
    next.cancel = { ...next.cancel, label: translateToastValue(next.cancel.label) };
  }
  return next;
}

function patchToastTranslations() {
  if (toastPatched) return;
  toastPatched = true;
  ["success", "error", "warning", "info", "message"].forEach((method) => {
    if (typeof toast[method] !== "function") return;
    const original = toast[method].bind(toast);
    try {
      toast[method] = (message, options) => original(translateToastValue(message), translateToastOptions(options));
    } catch {
      // If the toast method is read-only, DOM translation still covers rendered toasts.
    }
  });
}

function translateTextNode(node, dictionary) {
  const cached = textNodes.get(node);
  const current = node.nodeValue;
  const original = cached && (current === cached.translated || current === cached.original)
    ? cached.original
    : current;
  const translated = translateText(original, dictionary);
  textNodes.set(node, { original, translated });
  if (node.nodeValue !== translated) node.nodeValue = translated;
}

function getAttributeMap(element) {
  if (!attrValues.has(element)) attrValues.set(element, {});
  return attrValues.get(element);
}

function translateAttributes(element, dictionary) {
  const originalAttrs = getAttributeMap(element);
  translatedAttrNames.forEach((name) => {
    if (!element.hasAttribute(name)) return;
    const current = element.getAttribute(name);
    const cached = originalAttrs[name];
    const original = cached && (current === cached.translated || current === cached.original)
      ? cached.original
      : current;
    const translated = translateText(original, dictionary);
    originalAttrs[name] = { original, translated };
    if (element.getAttribute(name) !== translated) element.setAttribute(name, translated);
  });
}

function shouldSkip(element) {
  return ["SCRIPT", "STYLE", "NOSCRIPT", "TEXTAREA"].includes(element.tagName)
    || element.closest?.('[data-no-translate="true"]');
}

function translateElement(element, dictionary) {
  if (element.tagName === "TEXTAREA") {
    translateAttributes(element, dictionary);
    return;
  }
  if (shouldSkip(element)) return;
  translateAttributes(element, dictionary);
  element.childNodes.forEach((child) => {
    if (child.nodeType === Node.TEXT_NODE) {
      translateTextNode(child, dictionary);
      return;
    }
    if (child.nodeType === Node.ELEMENT_NODE) translateElement(child, dictionary);
  });
}

function scheduleTranslate() {
  if (scheduled || typeof window === "undefined") return;
  scheduled = true;
  window.requestAnimationFrame(() => {
    scheduled = false;
    if (document.body) translateElement(document.body, getDictionary());
  });
}

export function startDomTranslator() {
  if (typeof window === "undefined" || observer) return;
  patchToastTranslations();
  scheduleTranslate();
  i18n.on("languageChanged", () => {
    scheduleTranslate();
    window.setTimeout(scheduleTranslate, 0);
    window.setTimeout(scheduleTranslate, 50);
    window.setTimeout(scheduleTranslate, 150);
  });
  observer = new MutationObserver((mutations) => {
    if (mutations.some((mutation) => mutation.type === "childList" || mutation.type === "characterData" || (mutation.type === "attributes" && translatedAttrNames.includes(mutation.attributeName)))) {
      scheduleTranslate();
    }
  });
  observer.observe(document.documentElement, {
    childList: true,
    characterData: true,
    subtree: true,
    attributes: true,
    attributeFilter: translatedAttrNames,
  });
}
